import { PassThrough, PassThroughOption } from "primeng/api";
/**
 * Custom pass-through(pt) options.
 * @template I Type of instance.
 *
 * @see {@link InputPasswordPassThrough}
 * @group Interface
 */
export interface InputPasswordPassThroughOptions<I = unknown> {
  /**
   * Used to pass attributes to the root's DOM element.
   */
  root?: PassThroughOption<HTMLInputElement, I>;
}
/**
 * Defines valid pass-through options in InputPassword.
 * @see {@link InputPasswordPassThroughOptions}
 *
 * @template I Type of instance.
 */
export type InputPasswordPassThrough<I = unknown> = PassThrough<I, InputPasswordPassThroughOptions<I>>;